{
  "genre": "Personal account of plans for a balcony herb-growing experiment",
  "voice": "First-person, informal and reflective, with practical intentions and explicit uncertainty",
  "atoms": [
    {
      "id": "a1",
      "statement": "The writer plans to grow herbs on their balcony this spring to have fresh ingredients available when cooking.",
      "source_ids": ["b0001"]
    },
    {
      "id": "a2",
      "statement": "The balcony receives direct morning sunlight but is shaded by the neighboring building in the afternoon.",
      "source_ids": ["b0001"]
    },
    {
      "id": "a3",
      "statement": "The writer has not measured the exact amount of sunlight and needs to do so before choosing all the plants.",
      "source_ids": ["b0001"]
    },
    {
      "id": "a4",
      "statement": "The writer initially prefers basil, mint, and parsley, but may revise this list after learning more about their needs.",
      "source_ids": ["b0001"]
    },
    {
      "id": "a5",
      "statement": "Balcony space is limited, and the writer does not want pots to obstruct opening the balcony door.",
      "source_ids": ["b0002"]
    },
    {
      "id": "a6",
      "statement": "The writer intends to start with 3 containers rather than immediately fill the entire area, expecting this to help them assess maintenance requirements before making a larger commitment.",
      "source_ids": ["b0002"]
    },
    {
      "id": "a7",
      "statement": "The writer needs to check that the containers have drainage holes and that water underneath them will not cause problems for their downstairs neighbor.",
      "source_ids": ["b0002"]
    },
    {
      "id": "a8",
      "statement": "The first-stage budget is $60 and must cover containers, potting mix, and plants.",
      "source_ids": ["b0003"]
    },
    {
      "id": "a9",
      "statement": "The writer already owns a small watering can and does not expect to buy another.",
      "source_ids": ["b0003"]
    },
    {
      "id": "a10",
      "statement": "If the total cost exceeds expectations, the writer will reduce the number of plants rather than increase the budget.",
      "source_ids": ["b0003"]
    },
    {
      "id": "a11",
      "statement": "The writer wants the undertaking to remain a manageable experiment rather than become an expensive project.",
      "source_ids": ["b0003"]
    },
    {
      "id": "a12",
      "statement": "Watering is the aspect the writer is most uncertain about; they sometimes travel for work and cannot assume a neighbor will always be available to help.",
      "source_ids": ["b0004"]
    },
    {
      "id": "a13",
      "statement": "Before buying anything, the writer will consider what would happen if they were away for 4 days.",
      "source_ids": ["b0004"]
    },
    {
      "id": "a14",
      "statement": "A simple self-watering container might help, but the writer has not compared prices or checked its suitability for their preferred plants.",
      "source_ids": ["b0004"]
    },
    {
      "id": "a15",
      "statement": "The writer hopes to begin on 18 April, conditional on suitable weather and completion of the necessary checks.",
      "source_ids": ["b0005"]
    },
    {
      "id": "a16",
      "statement": "After the first month, the writer will review which plants are doing well and whether they enjoy the routine.",
      "source_ids": ["b0005"]
    },
    {
      "id": "a17",
      "statement": "If the experiment succeeds, the writer may add another herb later.",
      "source_ids": ["b0005"]
    },
    {
      "id": "a18",
      "statement": "The writer's current goal is to learn and grow a small amount of food without taking on more than they can comfortably maintain.",
      "source_ids": ["b0005"]
    }
  ]
}

